using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using System.Threading;using System.Web.Script.Serialization;using ReplierDesktop;
public static class SceneThinkingProbe {
 public static int Main(string[] a){try{var json=new JavaScriptSerializer();var records=new List<object>();foreach(string name in DualCommentService.Models)using(var m=new LocalModel(Path.Combine(a[0],"extension/.runtime/replier-llm"),name)){
 foreach(bool thinking in new[]{false,true}){var watch=Stopwatch.StartNew();var body=new{model=name,stream=false,think=thinking,keep_alive="30s",options=new{temperature=0.4,num_ctx=8192,num_predict=thinking?1800:300},format=new{type="object",properties=new{comments=new{type="array",minItems=1,maxItems=1,items=new{type="string"}}},required=new[]{"comments"}},messages=new[]{new{role="system",content="영상 시청자가 남기는 한국어 댓글을 한 문장 씁니다. 편한 존댓말로 짧게, 내 감상 하나만 말하세요. 상황을 설명하는 요약문이 아니라 보고 든 마음을 말합니다. comments JSON으로 답하세요."},new{role="user",content="영상 제목: 200렙 찍자마자 750만원 혼줌작 때려서 만든 미친매물 ㅋㅋㅋㅋㅋㅋㅋ\n실제 상황: 장비 옵션을 맞추려고 돈을 많이 쓰며 여러 번 시도합니다. 마지막 옵션이 잘 나왔다고 말하면서도 다른 옵션은 아깝다고 합니다.\n이번 댓글 관점: 돈이 계속 들어가는 걸 옆에서 지켜본 시청자의 반응"}}};try{string result=m.Chat(body,CancellationToken.None).GetAwaiter().GetResult();records.Add(new{model=name,thinking=thinking,seconds=watch.Elapsed.TotalSeconds,response=result});Console.WriteLine(name+" think="+thinking+" "+result+" "+watch.Elapsed.TotalSeconds.ToString("F1"));}catch(Exception e){Console.WriteLine(e.Message);} }
 m.Unload().GetAwaiter().GetResult();}File.WriteAllText(Path.Combine(a[0],"extension/data/replier-grounded-checks/scene-thinking-probe.json"),json.Serialize(records));return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
